#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int maximumLength(std::string s) {
        std::vector<int> runs[26];
        int n = s.size();
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && s[j] == s[i]) ++j;
            runs[s[i] - 'a'].push_back(j - i);
            i = j;
        }
        int ans = -1;
        for (int c = 0; c < 26; ++c) {
            auto& v = runs[c];
            if (v.empty()) continue;
            std::sort(v.rbegin(), v.rend());
            int l1 = v[0];
            int l2 = v.size() > 1 ? v[1] : 0;
            int l3 = v.size() > 2 ? v[2] : 0;
            int cand = std::max({l1 - 2, std::min(l1 - 1, l2), l3});
            if (cand > 0) {
                ans = std::max(ans, cand);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maximumLength(String s) {
        List<Integer>[] runs = new List[26];
        for (int i = 0; i < 26; i++) runs[i] = new ArrayList<>();
        int n = s.length();
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            runs[s.charAt(i) - 'a'].add(j - i);
            i = j;
        }
        int ans = -1;
        for (int c = 0; c < 26; c++) {
            List<Integer> v = runs[c];
            if (v.isEmpty()) continue;
            v.sort(Collections.reverseOrder());
            int l1 = v.get(0);
            int l2 = v.size() > 1 ? v.get(1) : 0;
            int l3 = v.size() > 2 ? v.get(2) : 0;
            int cand = Math.max(l1 - 2, Math.max(Math.min(l1 - 1, l2), l3));
            if (cand > 0) {
                ans = Math.max(ans, cand);
            }
        }
        return ans;
    }
}

